function DetailRow(props: {
  label: React.ReactNode
  value: React.ReactNode
  mono?: boolean
  muted?: boolean
}) {
  return (
    <div className='grid min-w-0 grid-cols-[5.25rem_minmax(0,1fr)] gap-2 text-sm sm:grid-cols-[7rem_minmax(0,1fr)] sm:gap-3'>
      <span className='text-muted-foreground min-w-0 text-xs'>
        {props.label}
      </span>
      <span
        className={cn(
          'max-w-full min-w-0 text-xs break-all sm:wrap-break-word',
          props.mono && 'font-mono',
          props.muted && 'text-muted-foreground'
        )}
      >
        {props.value}
      </span>
    </div>
  )
}

function DetailSection(props: {
  icon?: React.ReactNode
  iconTone?: IconBadgeTone
  label: string
  variant?: 'default' | 'danger'
  children: React.ReactNode
}) {
  const isDanger = props.variant === 'danger'
  const iconTone = isDanger ? 'destructive' : props.iconTone
  return (
    <div className='min-w-0 space-y-1.5'>
      <Label
        className={cn(
          'flex items-center gap-1.5 text-xs font-semibold',
          isDanger && 'text-red-500'
        )}
      >
        {props.icon && (
          <IconBadge tone={iconTone} size='xs'>
            {props.icon}
          </IconBadge>
        )}
        {props.label}
      </Label>
      <div
        className={cn(
          'min-w-0 space-y-1 overflow-hidden rounded-md border p-2.5 max-sm:p-2',
          isDanger
            ? 'border-red-200 bg-red-50 dark:border-red-900 dark:bg-red-950/20'
            : 'bg-muted/30'
        )}
      >
        {props.children}
      </div>
    </div>
  )
}

function hasRequestDebugData(
  requestDebugEntry: RequestDebugEntry | undefined
): boolean {
  if (!requestDebugEntry) return false
  return (
    requestDebugEntry.headers != null ||
    requestDebugEntry.method != null ||
    requestDebugEntry.url != null ||
    requestDebugEntry.host != null ||
    requestDebugEntry.remote_addr != null ||
    requestDebugEntry.body_bytes != null ||
    requestDebugEntry.body_bytes_known != null ||
    requestDebugEntry.body != null ||
    requestDebugEntry.body_available != null ||
    requestDebugEntry.body_ref != null ||
    requestDebugEntry.body_encoding != null ||
    requestDebugEntry.body_truncated != null ||
    requestDebugEntry.stored_bytes != null ||
    requestDebugEntry.content_type != null ||
    requestDebugEntry.compression != null ||
    requestDebugEntry.status != null ||
    requestDebugEntry.protocol != null ||
    requestDebugEntry.truncated != null
  )
}

function RequestDiagnosticsGroup(props: {
  label: string
  requestDebugEntry: RequestDebugEntry | undefined
  requestId?: string
  isRoot?: boolean
}) {
  const { t } = useTranslation()
  const requestDebugEntry = props.requestDebugEntry
  const [fullBody, setFullBody] = useState<string | null>(null)
  const [fullBodyLoading, setFullBodyLoading] = useState(false)
  const [fullBodyError, setFullBodyError] = useState<string | null>(null)
  if (!hasRequestDebugData(requestDebugEntry) || !requestDebugEntry) return null

  const headers = requestDebugEntry.headers
  const headersJson =
    headers && Object.keys(headers).length > 0
      ? JSON.stringify(headers, null, 2)
      : null
  const canLoadFullBody =
    props.isRoot === true &&
    requestDebugEntry.body_available === true &&
    !!requestDebugEntry.body_ref

  const loadFullBody = async () => {
    const bodyRequestId = requestDebugEntry.body_ref || props.requestId
    if (!bodyRequestId || fullBodyLoading) {
      return
    }
    setFullBodyLoading(true)
    setFullBodyError(null)
    try {
      const response = await getRequestDebugBody(bodyRequestId)
      if (!response.success || response.data?.body == null) {
        throw new Error(response.message || t('Request body not available'))
      }
      setFullBody(response.data.body)
    } catch (error) {
      setFullBodyError(
        error instanceof Error ? error.message : t('Request body not available')
      )
    } finally {
      setFullBodyLoading(false)
    }
  }

  return (
    <div className='bg-background/60 min-w-0 space-y-2 rounded-md border p-2.5'>
      <p className='text-xs font-semibold'>{props.label}</p>
      <div className='min-w-0 space-y-1.5'>
        {requestDebugEntry.remote_addr && (
          <DetailRow
            label={t('Remote Address')}
            value={requestDebugEntry.remote_addr}
            mono
          />
        )}
        {requestDebugEntry.url && (
          <DetailRow label={t('URL')} value={requestDebugEntry.url} mono />
        )}
        {requestDebugEntry.method && (
          <DetailRow
            label={t('Method')}
            value={requestDebugEntry.method}
            mono
          />
        )}
        {requestDebugEntry.host && (
          <DetailRow label={t('Host')} value={requestDebugEntry.host} mono />
        )}
        {requestDebugEntry.body_bytes != null && (
          <DetailRow
            label={t('Body Bytes')}
            value={requestDebugEntry.body_bytes.toLocaleString()}
            mono
          />
        )}
        {requestDebugEntry.body_bytes_known != null && (
          <DetailRow
            label={t('Body Bytes Known')}
            value={requestDebugEntry.body_bytes_known ? t('Yes') : t('No')}
          />
        )}
        {requestDebugEntry.body_encoding && (
          <DetailRow
            label={t('Body Encoding')}
            value={requestDebugEntry.body_encoding}
            mono
          />
        )}
        {requestDebugEntry.body_truncated != null && (
          <DetailRow
            label={t('Body Truncated')}
            value={requestDebugEntry.body_truncated ? t('Yes') : t('No')}
          />
        )}
        {requestDebugEntry.stored_bytes != null && (
          <DetailRow
            label={t('Stored Bytes')}
            value={requestDebugEntry.stored_bytes.toLocaleString()}
            mono
          />
        )}
        {requestDebugEntry.content_type && (
          <DetailRow
            label={t('Content Type')}
            value={requestDebugEntry.content_type}
            mono
          />
        )}
        {requestDebugEntry.compression && (
          <DetailRow
            label={t('Compression')}
            value={requestDebugEntry.compression}
            mono
          />
        )}
        {requestDebugEntry.status != null && (
          <DetailRow
            label={t('Status')}
            value={String(requestDebugEntry.status)}
            mono
          />
        )}
        {requestDebugEntry.protocol && (
          <DetailRow
            label={t('Protocol')}
            value={requestDebugEntry.protocol}
            mono
          />
        )}
        {requestDebugEntry.truncated != null && (
          <DetailRow
            label={t('Truncated')}
            value={requestDebugEntry.truncated ? t('Yes') : t('No')}
          />
        )}
      </div>
      {headersJson && (
        <div className='min-w-0 space-y-1.5'>
          <p className='text-muted-foreground text-xs'>{t('Headers')}</p>
          <pre className='bg-muted/50 max-h-40 max-w-full overflow-auto rounded border p-2 font-mono text-[11px] leading-relaxed break-all whitespace-pre-wrap'>
            {headersJson}
          </pre>
        </div>
      )}
      {requestDebugEntry.body != null && (
        <div className='min-w-0 space-y-1.5'>
          <p className='text-muted-foreground text-xs'>{t('Request Body')}</p>
          <pre className='bg-muted/50 max-h-64 max-w-full overflow-auto rounded border p-2 font-mono text-[11px] leading-relaxed break-all whitespace-pre-wrap'>
            {requestDebugEntry.body}
          </pre>
        </div>
      )}
      {canLoadFullBody && fullBody == null && (
        <div className='flex flex-wrap items-center gap-2'>
          <Button
            type='button'
            size='sm'
            variant='outline'
            onClick={loadFullBody}
            disabled={fullBodyLoading}
          >
            {fullBodyLoading ? (
              <Loader2 className='size-4 animate-spin' />
            ) : (
              <Eye className='size-4' />
            )}
            {t('Load full request body')}
          </Button>
          {fullBodyError && (
            <span className='text-destructive text-xs'>{fullBodyError}</span>
          )}
        </div>
      )}
      {fullBody != null && (
        <div className='min-w-0 space-y-1.5'>
          <p className='text-muted-foreground text-xs'>{t('Full request body')}</p>
          <pre className='bg-muted/50 max-h-[60vh] max-w-full overflow-auto rounded border p-2 font-mono text-[11px] leading-relaxed break-all whitespace-pre-wrap'>
            {fullBody}
          </pre>
        </div>
      )}
    </div>
  )
}

function RequestDiagnostics(props: {
  requestDebug: RequestDebug
